package br.com.dmp.widget
import android.content.Context
import android.graphics.Bitmap
import android.graphics.Canvas
import android.view.View
import android.widget.TextView
import android.widget.ListView
import android.widget.FrameLayout
import android.widget.ImageView
import org.json.JSONObject
import org.json.JSONArray
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.Shadows
import org.robolectric.annotation.Config
import org.robolectric.annotation.GraphicsMode
import java.io.File
@RunWith(RobolectricTestRunner::class)
@Config(sdk=[35],qualifiers="mdpi")
@GraphicsMode(GraphicsMode.Mode.NATIVE)
class WidgetNextTest{
 private val c:Context get()=RuntimeEnvironment.getApplication()
 private fun event(id:String,day:String="2026-10-14",time:String="08:30",type:String="Personal",names:List<String> = emptyList(),source:String="google")=JSONObject().put("id",id).put("date",day).put("start",time).put("end","09:30").put("type",type).put("title",id).put("studentNames",JSONArray(names)).put("source",source)
 private fun source():JSONObject{val items=JSONArray().put(event("students",names=listOf("Rafael Carminatti","Rogério Novelli","Alexandre Deboni"))).put(event("task",time="07:30",type="Compromisso",source="todoist")).put(event("kids",time="15:00",type="Tênis Kids").put("color","#BC671C").put("category","Laranja"));for(day in listOf(1,3,4,5,6,7))items.put(event("d$day",java.time.LocalDate.parse("2026-10-14").plusDays(day.toLong()).toString()));return JSONObject().put("agenda",JSONObject().put("date","2026-10-14").put("items",items)).put("today",JSONObject().put("date","2026-10-14").put("programmed",14).put("attended",8).put("absent",6).put("remaining",0).put("eventDates",JSONArray(listOf("2026-10-14","2026-10-16"))).put("workouts",JSONArray().put(JSONObject().put("id","w1").put("type","STRENGTH")).put(JSONObject().put("id","w2").put("type","PILATES"))))}
 private fun view(id:Int,agenda:Boolean,h:Int=600,system:Float=1f):View{val config=android.content.res.Configuration(c.resources.configuration).apply{fontScale=system};val context=c.createConfigurationContext(config);val rv=WidgetRenderer.render(context,id,agenda,WidgetLayout(164,h,system),source(),null,null);val host=android.appwidget.AppWidgetHostView(context);val v=rv.apply(context,host);host.addView(v);host.measure(View.MeasureSpec.makeMeasureSpec(164,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));host.layout(0,0,164,h);return v}
 @Test fun sevenDaysSkipEmptyDatesAndExcludeDayEight(){val rows=AgendaRows.rows(source(),"2026-10-14");assertEquals(listOf("2026-10-14","2026-10-15","2026-10-17","2026-10-18","2026-10-19","2026-10-20"),rows.filter{it.event==null}.map{it.day});assertEquals(listOf("task","students","kids"),rows.filter{it.day=="2026-10-14"}.mapNotNull{it.event?.optString("id")});assertTrue(AgendaRows.heading("2026-10-15","2026-10-14").startsWith("AMANHÃ"));assertFalse(AgendaRows.heading("2026-10-17","2026-10-14").contains("AMANHÃ"));assertEquals(3,AgendaRows.events(source(),"2026-10-14",false).size)}
 @Test fun sourcePreventsStableIdCollisionAndCommitmentHasExactDestination(){val a=AgendaRow("event:2026-10-14:google:same","2026-10-14");val b=AgendaRow("event:2026-10-14:todoist:same","2026-10-14");assertNotEquals(a.stableId,b.stableId);val e=event("task",source="todoist",type="Compromisso");assertEquals(WidgetNavigation.path("commitment","2026-10-14","task"),WidgetNavigation.record(e))}
 @Test fun allParticipantNamesHaveTheirOwnLinesAndGrowRowHeight(){fun row(names:List<String>):View{val e=event("event",names=names);val rv=AgendaCollection.row(c,901,AgendaRow("key","2026-10-14",e),"2026-10-14");val v=rv.apply(c,FrameLayout(c));v.measure(View.MeasureSpec.makeMeasureSpec(164,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1000,View.MeasureSpec.AT_MOST));v.layout(0,0,164,v.measuredHeight);return v};val one=row(listOf("Ana Silva"));val three=row(listOf("Rafael Carminatti","Rogério Novelli","Alexandre Deboni"));assertTrue(three.height>one.height);assertEquals("Rafael Carminatti\nRogério Novelli\nAlexandre Deboni",three.findViewById<TextView>(R.id.row_title).text.toString());assertTrue(three.findViewById<TextView>(R.id.row_title).lineCount>=3)}
 @Test fun footerAndHintRemovedAndHeaderOpensWeek(){val v=view(902,true);assertNull(v.findViewById<View>(R.id.agenda));assertNull(v.findViewById<View>(R.id.more));assertTrue(v.findViewById<View>(R.id.header).performClick());assertEquals("/app?widget=agenda&date=2026-10-14&range=week",Shadows.shadowOf(RuntimeEnvironment.getApplication()).nextStartedActivity.getStringExtra("path"));assertTrue(AgendaCollection.viewport(WidgetLayout(164,600),(AgendaRows.rows(source(),"2026-10-14")+AgendaRows.rows(source(),"2026-10-14")))>=500)}
 @Test fun fontAndOpacityAreIndependentPerWidgetAndPersist(){WidgetSettings.save(c,903,70,8,true,true,true);WidgetSettings.saveFont(c,903,130);WidgetSettings.save(c,904,90,8,true,true,true);WidgetSettings.saveFont(c,904,90);try{assertEquals(130,WidgetSettings.font(c,903));assertEquals(90,WidgetSettings.font(c,904));val a=view(903,true);val b=view(904,true);assertEquals(178,a.findViewById<ImageView>(R.id.shell_bg).imageAlpha);assertEquals(229,b.findViewById<ImageView>(R.id.shell_bg).imageAlpha);assertTrue(a.findViewById<TextView>(R.id.header).textSize>b.findViewById<TextView>(R.id.header).textSize);WidgetSettings.saveFont(c,903,200);assertEquals(130,WidgetSettings.font(c,903));WidgetSettings.saveFont(c,904,50);assertEquals(90,WidgetSettings.font(c,904))}finally{WidgetSettings.remove(c,903);WidgetSettings.remove(c,904)};assertEquals(100,WidgetSettings.font(c,903))}
 @Test fun fontMatrixFitsCriticalContentAndListsContinueToScroll(){for(font in listOf(90,100,115,130))for(system in listOf(1f,1.3f))for(h in listOf(260,360,600,800))for(agenda in listOf(true,false)){WidgetSettings.saveFont(c,905,font);val v=view(905,agenda,h,system);assertTrue("shell font=$font sys=$system h=$h agenda=$agenda",v.findViewById<View>(R.id.shell).height<=h);if(!agenda){val b=v.findViewById<View>(R.id.open);val rect=android.graphics.Rect();b.getDrawingRect(rect);(v as android.view.ViewGroup).offsetDescendantRectToMyCoords(b,rect);assertTrue("footer font=$font sys=$system h=$h bottom=${rect.bottom}",rect.bottom<=h);val next=v.findViewById<View>(R.id.next);val time=v.findViewById<TextView>(R.id.next_time);assertTrue("next collapsed font=$font sys=$system h=$h next=${next.height}",next.height>=time.height);val title=v.findViewById<View>(R.id.next_title);val titleRect=android.graphics.Rect();title.getDrawingRect(titleRect);(v as android.view.ViewGroup).offsetDescendantRectToMyCoords(title,titleRect);val cardRect=android.graphics.Rect();next.getDrawingRect(cardRect);v.offsetDescendantRectToMyCoords(next,cardRect);assertTrue("title outside card font=$font sys=$system h=$h title=${titleRect.bottom} card=${cardRect.bottom}",titleRect.bottom<=cardRect.bottom)}else{val list=v.findViewById<ListView>(R.id.items);assertTrue(list.adapter.count>7);assertTrue(list.height>100)}};WidgetSettings.remove(c,905)}
 @Test fun markersAndCalendarClicksKeepTheirDate(){val v=view(906,false,800);fun texts(x:View):List<TextView>{return if(x is android.view.ViewGroup)(0 until x.childCount).flatMap{texts(x.getChildAt(it))}else if(x is TextView)listOf(x)else emptyList()}
 val marked=texts(v.findViewById(R.id.calendar)).first{it.text.toString().replace("\n","")=="16•"};assertTrue(marked.performClick());assertEquals(WidgetNavigation.path("agenda","2026-10-16"),Shadows.shadowOf(RuntimeEnvironment.getApplication()).nextStartedActivity.getStringExtra("path"));assertNotNull(texts(v.findViewById(R.id.calendar)).find{it.text.toString().replace("\n","")=="14•"});}
 @Test fun renderWeekAndLargeFontReferences(){val dir=File("build/widget-previews");dir.mkdirs();for(agenda in listOf(true,false))for(font in listOf(100,130)){WidgetSettings.saveFont(c,907,font);val v=view(907,agenda,800);val image=Bitmap.createBitmap(164,800,Bitmap.Config.ARGB_8888);v.draw(Canvas(image));File(dir,(if(agenda)"agenda"else "hoje")+"-font$font.png").outputStream().use{image.compress(Bitmap.CompressFormat.PNG,100,it)}};WidgetSettings.remove(c,907)}
}
